// The Map scene's app (scenes.frameos.net/s/map): the view around a latitude and
// longitude, drawn from maps.frameos.net/v1/lines in one of four themes. The JSON's
// paths are already in the frame's pixels; get() returns them as JSX. The demo at
// maps.frameos.net/demo/ runs this file. On a touch screen a finger drags the map and two
// pinch it; e-paper waits for the finger to lift.

// Each theme: the land and its areas, the water, buildings, lines, roads (with an
// edge under them where `edge` has the kind, and `roadWidth` times the usual width)
// and the names.
const THEMES = {
  light: {
    land: "#f5f3ee", water: "#a7d3f5", shore: null, rivers: "#86bdee",
    areas: { farmland: "#f0eedf", grass: "#e4efd8", sand: "#f4ead2", ice: "#ffffff", urban: "#ebe7e0", park: "#d1ebc4", wood: "#c2e0b0" },
    building: "#ddd6cb", buildingEdge: "#c9c0b2",
    border: "#9b7bc4", borderGlow: "#e6dcf3", region: "#b9a6d4", rail: "#aaa3b3",
    road: { path: "#cbc4b6", minor_road: "#ffffff", major_road: "#ffe08a", highway: "#ffb35c" },
    edge: { minor_road: "#dcd6cb", major_road: "#e8c062", highway: "#e08a3a" },
    text: "#25282d", halo: "#ffffff", country: "#59467c", regionText: "#8e83a3", waterText: "#3f79b0", hood: "#767b84", pin: "#e5484d",
  },
  dark: {
    land: "#0f2236", water: "#17385a", shore: "#4f86bd", rivers: "#5fb0ff",
    areas: { farmland: "#12263b", grass: "#112a39", sand: "#1b2b3b", ice: "#203448", urban: "#162a43", park: "#0f3036", wood: "#0d3230" },
    building: "#1c3352", buildingEdge: "#2a4670",
    border: "#ff7aa8", borderGlow: "#3a2a4c", region: "#c46d93", rail: "#c4b5fd",
    road: { path: "#8995a3", minor_road: "#c9d2dc", major_road: "#f39c5a", highway: "#ffcf5c" },
    edge: {},
    text: "#ffffff", halo: "#0f2236", country: "#ffc4d8", regionText: "#aebcd0", waterText: "#7fb6ef", hood: "#a3b2c4", pin: "#ff7aa8",
  },
  vintage: {
    land: "#efe6cf", water: "#b8d4c8", shore: "#8eb3a3", rivers: "#94bcae",
    areas: { farmland: "#ebe1c4", grass: "#e2e2c0", sand: "#f1e3bf", ice: "#f8f4e9", urban: "#e3d6bb", park: "#cfd8a8", wood: "#bfcf9c" },
    building: "#dccbaa", buildingEdge: "#c6ae86",
    border: "#a0604d", borderGlow: "#e6cdb6", region: "#bb9a83", rail: "#8c7a64",
    road: { path: "#c9b896", minor_road: "#fbf6ea", major_road: "#f0cf8a", highway: "#e3a067" },
    edge: { minor_road: "#d9c9a6", major_road: "#c9a462", highway: "#b57446" },
    text: "#43362a", halo: "#f6efdc", country: "#7a3f2e", regionText: "#94765e", waterText: "#4e7f70", hood: "#7e6b57", pin: "#b8432f",
  },
  mono: {
    land: "#ffffff", water: "#000000", shore: null, rivers: "#000000",
    areas: {},
    building: "#ffffff", buildingEdge: "#000000",
    border: "#000000", borderGlow: null, region: "#000000", rail: "#000000",
    road: { path: "#000000", minor_road: "#000000", major_road: "#000000", highway: "#ffffff" },
    edge: { highway: "#000000" }, roadWidth: 0.55,
    text: "#000000", halo: "#ffffff", country: "#000000", regionText: "#000000", waterText: "#ffffff", hood: "#000000", pin: "#000000",
  },
}

// Web Mercator as /v1/lines draws it: 256 px tiles.
const world = (zoom) => 256 * 2 ** zoom
const project = (lat, lon, zoom) => [
  ((lon + 180) / 360) * world(zoom),
  (0.5 - Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360)) / (2 * Math.PI)) * world(zoom),
]
const unproject = (x, y, zoom) => [
  (Math.atan(Math.sinh(Math.PI - (2 * Math.PI * y) / world(zoom))) * 180) / Math.PI,
  (x / world(zoom)) * 360 - 180,
]

// Dragging and pinching. An LCD keeps the view's pixels in a canvas: the fingers only move
// those around, and the new view is fetched when the last finger lifts. Holding the canvas
// also keeps the app's interpreter, and its handlers, through a heavy render on an ESP32. A
// runtime too old to say what its panel is makes the canvas at the first press instead,
// since it may be an e-paper frame nobody can touch.
const HOME = { s: 1, x: 0, y: 0 }
let touched = false
let shown = null // the view the canvas holds
let failed = null // a view that could not be fetched: not asked for again on every move
let fingers = {} // where each pointer is now, by pointerId
let grip = {} // where each one was when the picture was at `base`
let base = HOME // the picture's place then: on screen, a map pixel is at pixel * s + (x, y)
let place = HOME // and its place now

const down = () => Object.keys(fingers).length
const here = (e) => ({ x: e.localX, y: e.localY, at: Date.now() })
const regrip = () => {
  base = place
  grip = { ...fingers }
}
const rest = () => {
  place = HOME
  regrip()
}

function gestures(c, w, h, scale) {
  const z = Number(c.zoom)
  const midpoint = (at, a, b) => ({ x: (at[a].x + at[b].x) / 2, y: (at[a].y + at[b].y) / 2 })
  const span = (at, a, b) => Math.hypot(at[b].x - at[a].x, at[b].y - at[a].y)
  const follow = () => {
    const [a, b] = Object.keys(fingers)
    if (b === undefined) {
      place = { s: base.s, x: base.x + fingers[a].x - grip[a].x, y: base.y + fingers[a].y - grip[a].y }
      return
    }
    // The point between the fingers stays under them, and the zoom stays one the service has.
    // A pinch stops short of 4x: an older runtime copies the picture at that size to scale it.
    const most = Math.min(3.9, 2 ** (20 - z)) / base.s
    const least = Math.max(0.25, 2 ** -z) / base.s
    const k = Math.min(most, Math.max(least, span(fingers, a, b) / Math.max(1, span(grip, a, b))))
    const from = midpoint(grip, a, b)
    const to = midpoint(fingers, a, b)
    place = { s: base.s * k, x: to.x + k * (base.x - from.x), y: to.y + k * (base.y - from.y) }
  }
  const settle = ({ s, x, y }) => {
    if (Math.abs(x) < 3 && Math.abs(y) < 3 && Math.abs(s - 1) < 0.02) return
    const [cx, cy] = project(Number(c.latitude), Number(c.longitude), z)
    const [lat, lon] = unproject(cx + (w / 2 - x) / s - w / 2, cy + (h / 2 - y) / s - h / 2, z)
    frameos.setState("latitude", Number(Math.max(-85.05, Math.min(85.05, lat)).toFixed(6)))
    frameos.setState("longitude", Number((((lon + 540) % 360) - 180).toFixed(6)))
    frameos.setState("zoom", Number((z + Math.log2(s)).toFixed(2)))
  }
  return {
    press: (e) => {
      if (e.button) return
      touched = true
      // A pointer lost along the way sends no release: one silent for this long is gone. A finger
      // held still sends nothing either, so this is long.
      for (const id of Object.keys(fingers)) if (Date.now() - fingers[id].at > 30000) delete fingers[id]
      fingers[e.pointerId] = here(e)
      regrip()
    },
    drag: (e) => {
      if (!fingers[e.pointerId]) return
      fingers[e.pointerId] = here(e)
      follow()
    },
    lift: (e) => {
      if (!fingers[e.pointerId]) return
      fingers[e.pointerId] = here(e)
      follow()
      delete fingers[e.pointerId]
      regrip()
      if (!down()) settle(place)
    },
    // A whole drag as one event, for e-paper. It comes in the panel's pixels.
    swipe: (e) => settle({ s: 1, x: (e.x - e.startX) / scale, y: (e.y - e.startY) / scale }),
  }
}

// The view as SVG: its w x h pixels drawn W x H large.
function mapSvg(c, t, url, w, h, W, H) {
  const size = Number(c.labelSize) || 13
  const data = frameos.fetchJson(url)
  if (!data?.layers) throw new Error("No map lines")
  const L = data.layers

  // Lines grow with the zoom: hairlines for a continent, streets wide enough to read.
  const zf = Math.min(2.4, Math.max(0.4, 2 ** ((Number(c.zoom) - 10) / 3)))
  const low = Math.min(1, zf) // glows and borders thin out below zoom 10; roads have edges from 8.5
  const rw = t.roadWidth ?? 1
  const ROAD = { path: 0.6, minor_road: 0.9 * zf * rw, major_road: 1.5 * zf * rw, highway: 2.1 * zf * rw }
  // Without its edge (zoomed out), a road is drawn in its edge's color.
  const edged = zf >= 0.7
  const roadColor = (kind) => (!edged && t.edge[kind]) || t.road[kind]
  const RIVER = { river: 1.3, canal: 1.1, stream: 0.7, ditch: 0.5, drain: 0.5 }
  const line = (d, color, width, dash) => (
    <path d={d} fill="none" stroke={color} strokeWidth={width} strokeDasharray={dash}
      strokeLinecap="round" strokeLinejoin="round" />
  )

  // Names: countries in capitals, bigger cities larger, water in italics on its own color.
  const look = (p) => {
    if (p.kind === "country") return { text: p.name.toUpperCase(), size: size * 1.05, weight: 700, fill: t.country, halo: t.halo }
    if (p.kind === "sea") return { text: p.name, size: size * 1.05, weight: 400, fill: t.waterText, halo: t.water, italic: true }
    if (p.kind === "bay" || p.kind === "lake") return { text: p.name, size: size * 0.9, weight: 400, fill: t.waterText, halo: t.water, italic: true }
    if (p.kind === "region") return { text: p.name, size: size * 0.9, weight: 400, fill: t.regionText, halo: t.halo }
    if (p.kind === "locality") {
      const big = p.rank >= 12 ? 1.2 : p.rank >= 9 ? 1.05 : 0.92
      return { text: p.name, size: size * big, weight: big > 1 ? 700 : 600, fill: t.text, halo: t.halo }
    }
    return { text: p.name.toUpperCase(), size: size * 0.78, weight: 600, fill: t.hood, halo: t.halo }
  }
  const names = (L.places ?? []).map((p) => ({ x: p.x, y: p.y, ...look(p) }))
  const name = (n, halo) => (
    <text x={n.x} y={n.y} textAnchor="middle" dominantBaseline="middle" fontSize={n.size} fontWeight={n.weight}
      fontStyle={n.italic ? "italic" : undefined} fill={halo ? "none" : n.fill} stroke={halo ? n.halo : undefined}
      strokeWidth={halo ? Math.max(2.5, n.size / 4) : undefined} strokeLinejoin="round">{n.text}</text>
  )

  const roads = L.roads ?? []
  const countries = (L.boundaries ?? []).filter((f) => f.kind !== "region")
  const [px, py] = [w / 2, h / 2]
  const k = Math.max(1, size / 13)
  return (
    <svg width={W} height={H} viewBox={`0 0 ${w} ${h}`}>
      <rect width={w} height={h} fill={t.land} />
      {(L.land ?? []).filter((f) => t.areas[f.kind]).map((f) => <path d={f.fill} fill={t.areas[f.kind]} />)}
      {(L.water ?? []).map((f) => <path d={f.fill} fill={t.water} />)}
      {t.shore ? (L.water ?? []).map((f) => line(f.stroke, t.shore, 0.8)) : []}
      {(L.rivers ?? []).map((f) => line(f.d, t.rivers, (RIVER[f.kind] ?? 0.6) * Math.min(zf, 1.6)))}
      {(L.buildings ?? []).map((f) => <path d={f.fill} fill={t.building} stroke={t.buildingEdge} strokeWidth={0.6} />)}
      {t.borderGlow ? countries.map((f) => line(f.d, t.borderGlow, 2 + 3 * low)) : []}
      {(L.boundaries ?? []).map((f) => f.kind === "region"
        ? line(f.d, t.region, 0.4 + 0.4 * low, "3 3")
        : line(f.d, t.border, 0.8 + 0.5 * low, f.kind === "disputed" ? "2 3" : "7 3"))}
      {(L.rail ?? []).map((f) => line(f.d, t.rail, 1, "5 3"))}
      {edged ? roads.filter((f) => t.edge[f.kind]).map((f) => line(f.d, t.edge[f.kind], ROAD[f.kind] + 1.3 * low)) : []}
      {roads.map((f) => line(f.d, roadColor(f.kind), ROAD[f.kind], f.kind === "path" ? "2 2" : undefined))}
      {names.map((n) => name(n, true))}
      {names.map((n) => name(n, false))}
      {c.pin ? (
        <g>
          <path d={`M${px} ${py}L${px - 5.2 * k} ${py - 10.5 * k}A${6 * k} ${6 * k} 0 1 1 ${px + 5.2 * k} ${py - 10.5 * k}Z`}
            fill={t.pin} stroke={t.halo} strokeWidth={1.5 * k} strokeLinejoin="round" />
          <circle cx={px} cy={py - 13.5 * k} r={2.2 * k} fill={t.halo} />
        </g>
      ) : []}
      <text x={w - 5} y={h - 5} textAnchor="end" fontSize={10} fill="none" stroke={t.halo} strokeWidth={3}
        strokeLinejoin="round">{data.attribution}</text>
      <text x={w - 5} y={h - 5} textAnchor="end" fontSize={10} fill={t.text}>{data.attribution}</text>
    </svg>
  )
}

export function get(app, context) {
  const c = app.config
  const t = THEMES[c.theme] ?? THEMES.light
  const w = Math.round(context.targetWidth || context.imageWidth || app.frame.width)
  const h = Math.round(context.targetHeight || context.imageHeight || app.frame.height)
  const size = Number(c.labelSize) || 13
  // The most map data the frame can hold. An ESP32's canvas shares its memory: a 1.5 MB
  // view did not fit next to a 1200x1600 one. The service drops detail until it fits.
  const maxKb = c.maxKb === undefined || c.maxKb === "auto" ? (app.frame.embedded ? 400 : 0) : Number(c.maxKb) || 0
  const query = [
    `lat=${c.latitude}`, `lon=${c.longitude}`, `zoom=${c.zoom}`, `width=${w}`, `height=${h}`,
    "layers=land,water,buildings,rivers,roads,rail,boundaries,places",
    "rivers=river,canal,stream,ditch,drain", "roads=path,minor_road,major_road,highway",
    `places=${c.places},sea,bay,lake`, `detail=${c.detail}`, "simplify=0.5",
    // Names are drawn up to 1.2 times the size: thin them out at that size.
    `labels=${c.labels}`, `font=${Math.round(size * 1.2)}`,
    c.lang && c.lang !== "local" ? `lang=${c.lang}` : "",
    maxKb > 0 ? `maxkb=${maxKb}` : "",
  ]
  const url = `https://maps.frameos.net/v1/lines?${query.filter(Boolean).join("&")}`
  const scale = app.frame.scale || 1
  const { press, drag, lift, swipe } = gestures(c, w, h, scale)
  // E-paper shows nothing until the drag is over: no pixels to move, one refresh at the end.
  if (app.frame.paper) return <div onSwipe={swipe}>{mapSvg(c, t, url, w, h, w, h)}</div>
  if (!touched && app.frame.paper !== false) return <div onPointerDown={press}>{mapSvg(c, t, url, w, h, w, h)}</div>

  // In the panel's pixels, so the map stays sharp on a frame with a render scale.
  const canvas = frameos.canvas("map", Math.round(w * scale), Math.round(h * scale), t.land)
  const view = [url, c.theme, c.pin].join(" ")
  let drew = false
  if (canvas.fresh || (view !== shown && view !== failed)) {
    try {
      if (!frameos.draw(canvas, mapSvg(c, t, url, w, h, canvas.width, canvas.height))) throw new Error("it did not fit")
      shown = view
      failed = null
      drew = true
    } catch (err) {
      failed = view
      frameos.error(`No new map: ${err.message}`)
    }
  }
  // The new view is in, or none is coming: the picture goes back to its place.
  if (drew || !down()) rest()
  const { s, x, y } = place
  return (
    <div onPointerDown={press} onPointerMove={down() ? drag : null} onPointerUp={lift}>
      <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`}>
        <rect width={w} height={h} fill={t.land} />
        <image href={canvas} x={s === 1 ? Math.round(x) : x} y={s === 1 ? Math.round(y) : y} width={w * s} height={h * s}
          preserveAspectRatio="none" imageRendering="pixelated" />
      </svg>
    </div>
  )
}

