// A mouse wheel over the map: a notch is half a zoom level, around the point under the
// cursor. The wheel is a browser's or a Pi's mouse; an ESP32 has none.
const world = (zoom) => 256 * 2 ** zoom
const project = (lat, lon, zoom) => [
  ((lon + 180) / 360) * world(zoom),
  (0.5 - Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360)) / (2 * Math.PI)) * world(zoom),
]
const unproject = (x, y, zoom) => [
  (Math.atan(Math.sinh(Math.PI - (2 * Math.PI * y) / world(zoom))) * 180) / Math.PI,
  (x / world(zoom)) * 360 - 180,
]

export function run(app, context) {
  const { deltaY, x, y } = context.payload
  const zoom = Number(app.state.zoom)
  const next = Math.max(0, Math.min(20, zoom - deltaY * 0.5))
  if (!deltaY || next === zoom) return
  // The payload is in the panel's pixels and the map's are that divided by the scale.
  const scale = app.frame.scale || 1
  const turned = app.frame.rotate === 90 || app.frame.rotate === 270
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const moved = 1 - 2 ** (zoom - next)
  const [cx, cy] = project(Number(app.state.latitude), Number(app.state.longitude), zoom)
  const [lat, lon] = unproject(cx + ((x - width / 2) / scale) * moved, cy + ((y - height / 2) / scale) * moved, zoom)
  frameos.setState("latitude", Number(Math.max(-85.05, Math.min(85.05, lat)).toFixed(6)))
  frameos.setState("longitude", Number((((lon + 540) % 360) - 180).toFixed(6)))
  frameos.setState("zoom", Number(next.toFixed(2)))
}
